func newRecurringEarning() unsafe.Pointer { return unsafe.Pointer(new(recurringpay.RecurringEarning)) }

func newNRecurringEarning(n int) unsafe.Pointer {
	return unsafe.Pointer(unsafe.SliceData(make([]recurringpay.RecurringEarning, n)))
}

func ptrRecurringEarning(p unsafe.Pointer, c int32) any {
	r := (*recurringpay.RecurringEarning)(p)
	switch c {
	case 0:
		return (*string)(unsafe.Pointer(&r.ID))
	case 1:
		return (*string)(unsafe.Pointer(&r.BusinessUnitID))
	case 2:
		return (*string)(unsafe.Pointer(&r.OrganizationID))
	case 3:
		return (*string)(unsafe.Pointer(&r.WorkerID))
	case 4:
		return (*string)(unsafe.Pointer(&r.PayCodeID))
	case 5:
		return (*string)(unsafe.Pointer(&r.Status))
	case 6:
		return (*string)(unsafe.Pointer(&r.Kind))
	case 7:
		return (*string)(unsafe.Pointer(&r.Frequency))
	case 8:
		return &r.Description
	case 9:
		return &r.AmountMinor
	case 10:
		return &r.TotalCapMinor
	case 11:
		return &r.PaidToDateMinor
	case 12:
		return &r.StartDate
	case 13:
		return &r.EndDate
	case 14:
		return &r.CurrencyCode
	case 15:
		return (*string)(unsafe.Pointer(&r.CreatedByID))
	case 16:
		return &r.Version
	case 17:
		return &r.CreatedAt
	case 18:
		return &r.UpdatedAt
	}
	return nil
}

func valueRecurringEarning(p unsafe.Pointer, c int32) any {
	r := (*recurringpay.RecurringEarning)(p)
	switch c {
	case 0:
		return string(r.ID)
	case 1:
		return string(r.BusinessUnitID)
	case 2:
		return string(r.OrganizationID)
	case 3:
		return string(r.WorkerID)
	case 4:
		return string(r.PayCodeID)
	case 5:
		return string(r.Status)
	case 6:
		return string(r.Kind)
	case 7:
		return string(r.Frequency)
	case 8:
		return r.Description
	case 9:
		return r.AmountMinor
	case 10:
		if r.TotalCapMinor == nil {
			return nil
		}
		return *r.TotalCapMinor
	case 11:
		return r.PaidToDateMinor
	case 12:
		return r.StartDate
	case 13:
		if r.EndDate == nil {
			return nil
		}
		return *r.EndDate
	case 14:
		return r.CurrencyCode
	case 15:
		if r.CreatedByID == "" {
			return nil
		}
		return string(r.CreatedByID)
	case 16:
		return r.Version
	case 17:
		return r.CreatedAt
	case 18:
		return r.UpdatedAt
	}
	return nil
}

func attachRecurringEarning(p unsafe.Pointer, rel int32, child unsafe.Pointer) {
	r := (*recurringpay.RecurringEarning)(p)
	switch rel {
	case 0:
		r.Worker = (*worker.Worker)(child)
	case 1:
		r.PayCode = (*paycode.PayCode)(child)
	}
}

func beforeCreateRecurringEarning(ctx context.Context, p unsafe.Pointer) error {
	return (*recurringpay.RecurringEarning)(p).BeforeCreate(ctx)
}

